// www/app/push.js
// Push notification handling for incoming calls

import { logLine } from "./log.js";

// VAPID public key - will be generated by push server
// You'll need to replace this with your actual public key after running the push server setup
const VAPID_PUBLIC_KEY = 'BIIM6yQ1rQ6xjGbrqddWBczRJ6jEV9inqGb83Qy28Z5CnlFSsNTp0LqCQVZnFSlzQIW83WctYBCyaIKiRf_OU3w';

let pushSubscription = null;
let pushEnabled = false;

// Convert VAPID key from base64 to Uint8Array
function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding)
    .replace(/\-/g, '+')
    .replace(/_/g, '/');
  
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
}

// Check if push notifications are supported
export function isPushSupported() {
  return 'serviceWorker' in navigator && 
         'PushManager' in window && 
         'Notification' in window;
}

// Register service worker
export async function registerServiceWorker() {
  if (!('serviceWorker' in navigator)) {
    logLine('[Push] Service workers not supported');
    return null;
  }

  try {
    const registration = await navigator.serviceWorker.register('/sw.js');
    logLine('[Push] Service worker registered');
    
    // Wait for service worker to be ready
    await navigator.serviceWorker.ready;
    logLine('[Push] Service worker ready');
    
    return registration;
  } catch (error) {
    console.error('[Push] Service worker registration failed:', error);
    logLine('[Push] Service worker registration failed: ' + error.message);
    return null;
  }
}

// Request notification permission
export async function requestNotificationPermission() {
  if (!('Notification' in window)) {
    logLine('[Push] Notifications not supported');
    return 'denied';
  }

  if (Notification.permission === 'granted') {
    logLine('[Push] Notification permission already granted');
    return 'granted';
  }

  if (Notification.permission === 'denied') {
    logLine('[Push] Notification permission denied');
    return 'denied';
  }

  try {
    const permission = await Notification.requestPermission();
    logLine(`[Push] Notification permission: ${permission}`);
    return permission;
  } catch (error) {
    console.error('[Push] Error requesting notification permission:', error);
    return 'denied';
  }
}

// Subscribe to push notifications
export async function subscribeToPush(extension) {
  if (!isPushSupported()) {
    logLine('[Push] Push notifications not supported');
    return null;
  }

  if (VAPID_PUBLIC_KEY === 'YOUR_VAPID_PUBLIC_KEY_HERE' || !VAPID_PUBLIC_KEY) {
    logLine('[Push] WARNING: VAPID public key not configured');
    logLine('[Push] Please run push server setup and update VAPID_PUBLIC_KEY');
    return null;
  }

  try {
    // Request permission first
    const permission = await requestNotificationPermission();
    if (permission !== 'granted') {
      logLine('[Push] Notification permission not granted');
      return null;
    }

    // Get service worker registration
    const registration = await navigator.serviceWorker.ready;
    
    // Check if already subscribed
    let subscription = await registration.pushManager.getSubscription();
    
    if (!subscription) {
      // Create new subscription
      logLine('[Push] Creating new push subscription...');
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
      });
      logLine('[Push] Push subscription created');
    } else {
      logLine('[Push] Using existing push subscription');
    }

    pushSubscription = subscription;
    pushEnabled = true;

    // Send subscription to server
    await sendSubscriptionToServer(subscription, extension);
    
    return subscription;
  } catch (error) {
    console.error('[Push] Error subscribing to push:', error);
    logLine('[Push] Subscription failed: ' + error.message);
    return null;
  }
}

// Unsubscribe from push notifications
export async function unsubscribeFromPush(extension) {
  if (!pushSubscription) {
    return;
  }

  try {
    // Remove from server first
    await removeSubscriptionFromServer(pushSubscription, extension);
    
    // Unsubscribe locally
    await pushSubscription.unsubscribe();
    logLine('[Push] Unsubscribed from push notifications');
    
    pushSubscription = null;
    pushEnabled = false;
  } catch (error) {
    console.error('[Push] Error unsubscribing:', error);
  }
}

// Send subscription to push server
async function sendSubscriptionToServer(subscription, extension) {
  try {
    const response = await fetch('/api/push/subscribe', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        extension: extension,
        subscription: subscription.toJSON()
      })
    });

    if (!response.ok) {
      throw new Error(`Server returned ${response.status}`);
    }

    logLine('[Push] Subscription registered with server');
    return await response.json();
  } catch (error) {
    console.error('[Push] Error sending subscription to server:', error);
    logLine('[Push] Failed to register subscription with server: ' + error.message);
    throw error;
  }
}

// Remove subscription from server
async function removeSubscriptionFromServer(subscription, extension) {
  try {
    const response = await fetch('/api/push/unsubscribe', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        extension: extension,
        endpoint: subscription.endpoint
      })
    });

    if (!response.ok) {
      throw new Error(`Server returned ${response.status}`);
    }

    logLine('[Push] Subscription removed from server');
  } catch (error) {
    console.error('[Push] Error removing subscription from server:', error);
  }
}

// Listen for service worker messages
export function setupServiceWorkerListener(onIncomingCall) {
  if (!('serviceWorker' in navigator)) return;

  navigator.serviceWorker.addEventListener('message', (event) => {
    logLine('[Push] Message from service worker:', JSON.stringify(event.data));
    
    if (event.data && event.data.type === 'incoming-call-action') {
      const { action, callId, from } = event.data;
      
      if (action === 'answer' && onIncomingCall) {
        logLine(`[Push] User chose to answer call from ${from}`);
        onIncomingCall({ action: 'answer', from, callId });
      } else if (action === 'reject') {
        logLine(`[Push] User rejected call from ${from}`);
        onIncomingCall({ action: 'reject', from, callId });
      }
    }
  });
}

// Get push status
export function getPushStatus() {
  return {
    supported: isPushSupported(),
    enabled: pushEnabled,
    permission: 'Notification' in window ? Notification.permission : 'unsupported',
    subscription: pushSubscription
  };
}

// Test push notification (for debugging)
export async function testPushNotification() {
  if (!isPushSupported()) {
    alert('Push notifications not supported');
    return;
  }

  const permission = await requestNotificationPermission();
  if (permission !== 'granted') {
    alert('Notification permission denied');
    return;
  }

  const registration = await navigator.serviceWorker.ready;
  registration.showNotification('Test Notification', {
    body: 'This is a test notification from WebPhone',
    icon: '/icon-192.png',
    badge: '/badge-72.png',
    tag: 'test',
    requireInteraction: false
  });
  
  logLine('[Push] Test notification shown');
}

// Initialize push notification system
export async function init() {
  if (!isPushSupported()) {
    logLine('[Push] Push notifications not supported in this browser');
    return false;
  }

  try {
    await registerServiceWorker();
    logLine('[Push] Push notification system initialized');
    return true;
  } catch (err) {
    logLine('[Push] Failed to initialize:', err);
    return false;
  }
}

// Subscribe to push notifications after successful registration
export async function subscribeAfterRegister(extension) {
  if (!extension) {
    logLine('[Push] Cannot subscribe: no extension provided');
    return false;
  }

  try {
    const permission = await requestNotificationPermission();
    if (permission !== 'granted') {
      logLine('[Push] Notification permission denied');
      return false;
    }

    const success = await subscribeToPush(extension);
    if (success) {
      logLine(`[Push] Subscribed to push notifications for extension ${extension}`);
    }
    return success;
  } catch (err) {
    logLine('[Push] Failed to subscribe:', err);
    return false;
  }
}
